'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils/constant-function' );
var degenerate = require( '@stdlib/stats/base/dists/degenerate/cdf' ).factory;
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var exp = require( '@stdlib/math/base/special/exp' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var erfc = require( '@stdlib/math/base/special/erfc' );
var PINF = require( '@stdlib/constants/float64/pinf' );


// MAIN //

/**
* Returns a function for evaluating the cumulative distribution function (CDF) for a Wald distribution.
*
* @param {number} mu - mean
* @param {NonNegativeNumber} lambda - shape parameter
* @returns {Function} function to evaluate the cumulative distribution function
*
* @example
* var cdf = factory( 1.0, 1.0 );
* var y = cdf( 2.0 );
* // returns ~0.885
*
* y = cdf( 0.5 );
* // returns ~0.365
*/
function factory( mu, lambda ) {
	var C;

	if (
		isnan( mu ) ||
		isnan( lambda ) ||
		mu <= 0.0 ||
		lambda < 0.0
	) {
		return constantFunction( NaN );
	}
	if ( lambda === 0.0 ) {
		return degenerate( mu );
	}
	C = exp( 2.0 * ( lambda / mu ) );
	return cdf;

	/**
	* Evaluates the cumulative distribution function (CDF) of a Wald distribution.
	*
	* @private
	* @param {number} x - input value
	* @returns {Probability} evaluated CDF
	*
	* @example
	* var y = cdf( 2.0 );
	* // returns <number>
	*/
	function cdf( x ) {
		var t1;
		var t2;
		var z;

		if ( isnan( x ) ) {
			return NaN;
		}
		if ( x <= 0.0 ) {
			return 0.0;
		}
		if ( x === PINF ) {
			return 1.0;
		}
		z = sqrt( lambda / x );

		// Φ(a) = 0.5 * erfc( -a / √2 )
		t1 = 0.5 * erfc( ( -z * ( ( x / mu ) - 1.0 ) ) / sqrt( 2.0 ) );
		t2 = C * 0.5 * erfc( ( z * ( ( x / mu ) + 1.0 ) ) / sqrt( 2.0 ) );
		return t1 + t2;
	}
}


// EXPORTS //

module.exports = factory;
